-- Criação do Banco de Dados
CREATE DATABASE IF NOT EXISTS sap_master_data;
-- USE sap_master_data; -- Omitido/comentado pois psql usa \c, mas mantendo o padrão solicitado.

-- Criação da Tabela de Serviços (Foco na limpeza inicial)
CREATE TABLE servicos_mock (
    id_servico SERIAL PRIMARY KEY,
    area_servico VARCHAR(50) NOT NULL,
    texto_breve VARCHAR(255) NOT NULL,
    abreviatura VARCHAR(10) NOT NULL,
    complemento VARCHAR(15) DEFAULT '',
    id1_condicao VARCHAR(50) NOT NULL CHECK (id1_condicao IN (
        'Hora normal',
        'Hora extra Seg a Sab',
        'Hora extra Dom/Feriado',
        'Adicional noturno (hora)',
        'Hora extra noturna Seg a Sab',
        'Hora extra noturna Dom/Feriado',
        'Adicional periculosidade (hora)',
        'Adicional periculosidade s/ hora extra',
        'Adicional periculosidade (mensal)',
        'Adicional insalubridade (hora)',
        'Posto mensal (equipe fixa)',
        'Mobilizacao / Desmobilizacao',
        'Retroativo',
        'Obs.: Itens que não são mão de obra'
    )),
    id2_nbs VARCHAR(20) NOT NULL,
    codigo_padronizado VARCHAR(40) UNIQUE NOT NULL,
    criador_codigo VARCHAR(100) NULL,
    data_criacao TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Adicionando comentários no padrão PostgreSQL
COMMENT ON COLUMN servicos_mock.area_servico IS 'Ex: Eletromecânica, Civil, Automação';
COMMENT ON COLUMN servicos_mock.texto_breve IS 'Nome completo do serviço sem abreviações';
COMMENT ON COLUMN servicos_mock.complemento IS 'Objeto principal do serviço (aprox. 6 caracteres)';
COMMENT ON COLUMN servicos_mock.id1_condicao IS 'Opções padronizadas de regime e condição';
COMMENT ON COLUMN servicos_mock.id2_nbs IS 'Código NBS vinculado';
COMMENT ON COLUMN servicos_mock.codigo_padronizado IS 'Concatenação final limpa: abrev + comp + sigla_id1 + _ + id2';
COMMENT ON COLUMN servicos_mock.criador_codigo IS 'Usuário que padronizou o registro';

-- Inserção dos registros

-- Consulta de Validação
SELECT 
    id_servico,
    area_servico,
    texto_breve,
    codigo_padronizado
FROM 
    servicos_mock;
